-- What's new for the 2026-11-19 evening release (OPI feedback round 2 on Project
-- Setup: speed, crew offers per estimate, crew pay rows, month-end expenses,
-- card order, Job Schedule differences, no hard refresh), published at deploy.
INSERT INTO release_notes (title, body, page, tour_key, capability, published_at, created_by)
SELECT * FROM (
  SELECT 'Faster Project Setup, Closeout and Cash Flow' AS title, 'Project Closeout opens straight away from a saved list (jobs you change show their new numbers at once), and the Cash Flow forecast and Project Setup load faster.' AS body, '#/closeout' AS page, NULL AS tour_key, 'page.assignment' AS capability, NOW() - INTERVAL 0 SECOND AS published_at, 'release-1119b' AS created_by
  UNION ALL SELECT 'Crew offers per estimate', 'Each estimate or change order has its own crew offer under Schedules, Crew payments. The offer email shows the payment schedule as a table that pastes into Outlook. Mark offer as sent saves the email and the payment schedule in the job''s 7 Notes folder. The Crew payments header shows every estimate''s offer status.', '#/setup', NULL, 'page.assignment', NOW() - INTERVAL 1 SECOND, 'release-1119b'
  UNION ALL SELECT 'Crew payments: send-invoice date and comments', 'Every crew payment has its pay date, amount, the date the crew sends its invoice and a comment. If the payments don''t add up to the estimate''s contract labor, the card says so: Re-balance, or Keep it when you''re paying more or less on purpose. Adding or removing a payment re-balances the ones nobody typed.', '#/setup', NULL, 'page.assignment', NOW() - INTERVAL 2 SECOND, 'release-1119b'
  UNION ALL SELECT 'Expenses at month-end', 'Materials, propane, rentals and travel are planned at the end of each month the work runs (open jobs were re-planned, edited plans were left alone). Lodging keeps Hotel Engine''s statements. A row you edited can go back to the app''s plan, and a plan that doesn''t add up offers Re-balance or Keep it.', '#/setup', NULL, 'page.assignment', NOW() - INTERVAL 3 SECOND, 'release-1119b'
  UNION ALL SELECT 'Project Setup: assignment cards in order', 'Assignment now reads Start and end dates, Job details, Project manager, Crew company assigned. Set one PM or one crew company for every estimate in one go, and the PM and crew availability update as you pick. Invoice dates read mm/dd/yy and a sent invoice has one expected-paid date everywhere.', '#/setup', NULL, 'page.assignment', NOW() - INTERVAL 4 SECOND, 'release-1119b'
  UNION ALL SELECT 'Job Schedule differences show up', 'When Ashley''s Job Schedule says different dates or crews than the app, the job is flagged on Project Setup (Job Schedule differs) and the bell tells you. On the date range, Use these takes the sheet''s values, Keep the app''s hides it until the sheet changes again.', '#/setup', NULL, 'page.assignment', NOW() - INTERVAL 5 SECOND, 'release-1119b'
  UNION ALL SELECT 'No more hard refresh', 'After an update the app tells you (The app was updated) and loads the new version on your next click.', '#/projects', NULL, NULL, NOW() - INTERVAL 6 SECOND, 'release-1119b'
) d
WHERE NOT EXISTS (SELECT 1 FROM release_notes WHERE created_by = 'release-1119b');
